<?php require __DIR__.'/vendor/autoload.php'; $app = require_once __DIR__.'/bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $employees = \App\Models\Employee::whereNotNull('user_id')->with('user')->get(); foreach ($employees as $emp) { if ($emp->user) { $emp->user->username = $emp->employee_code; $emp->user->save(); } } $users = \App\Models\User::whereNull('username')->get(); foreach ($users as $u) { if ($u->email) { $u->username = explode('@', $u->email)[0] . rand(100, 999); $u->save(); } elseif ($u->phone) { $u->username = $u->phone; $u->save(); } else { $u->username = 'user' . $u->id; $u->save(); } } echo 'Backfill complete.'; 
